'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['encodeRoute']);
const { encodeRoute } = api;

assert.strictEqual(encodeRoute([]), '/');
assert.strictEqual(encodeRoute(['a', '']), '/a/');
assert.strictEqual(encodeRoute(['', 'a', '']), '//a/');
assert.strictEqual(encodeRoute(['hello world', 'a/b', 'x?y=z', '100%']), '/hello%20world/a%2Fb/x%3Fy%3Dz/100%25');
assert.strictEqual(encodeRoute(['already%20encoded']), '/already%2520encoded');
assert.strictEqual(encodeRoute(['é', '😀']), '/%C3%A9/%F0%9F%98%80');
const segments = ['first', 'second'];
const snapshot = segments.slice();
assert.strictEqual(encodeRoute(segments), '/first/second');
assert.deepStrictEqual(segments, snapshot);
for (const bad of [null, {}, 'a', 1]) assert.throws(() => encodeRoute(bad), TypeError);
for (const bad of [[1], ['ok', null], [undefined], [{}], [[]]]) assert.throws(() => encodeRoute(bad), TypeError);
assert.throws(() => encodeRoute(['\uD800']), URIError);

